function eventRow(e){const d=e.date?new Date(e.date+'T12:00:00'):null;return `<div class="event-row"><div class="event-date"><strong>${d?d.getDate():'ВС'}</strong>${d?d.toLocaleDateString('ru',{month:'short'}).replace('.',''):'еженедельно'}</div><div class="event-info"><h3>${esc(e.title)}</h3><p>${esc(e.time)} · ${esc(e.place)}</p>${e.status==='cancelled'?'<p>Отменено из-за дождя</p>':''}</div>${status(e)}<button class="arrow-button" aria-label="Подробнее: ${esc(e.title)}" data-event="${esc(e.id)}">${icon('arrow')}</button></div>`}
function home(){const now=new Date();return `<div class="heading-row"><div><span class="eyebrow">ВАШ ХРАМ. ВАША ОБЩИНА.</span><h1>Харе Кришна!</h1><p class="sub">Рады быть вместе. Всё о жизни храма — здесь.</p></div><div class="date-stamp"><strong>${now.toLocaleDateString('ru',{day:'numeric',month:'long',timeZone:'Asia/Tbilisi'})}</strong>Батуми, Грузия</div></div><div class="home-grid"><section class="hero"><span class="pill"><span class="dot"></span>Каждое воскресенье</span><h2>Вместе петь.<br>Слушать.<br>Вдохновляться.</h2><p>Киртан, духовное общение и прасад.<br>На воскресный пир любви можно прийти каждому.</p><div class="hero-bottom"><span>Вход свободный</span><button data-event="sunday">О программе ${icon('arrow')}</button></div></section><section class="support-card"><span class="eyebrow">ХРАМ ЖИВЁТ ВАШЕЙ ЗАБОТОЙ</span><div class="heart">♡</div><h2>Маленький вклад.<br>Большое служение.</h2><p>Помогите храму оставаться местом встреч, заботы и духовного общения.</p><a class="button blue wide" href="#donations">Поддержать храм ${icon('arrow')}</a><div class="support-methods">TBC BANK · СБЕРБАНК · USDT</div></section></div><div class="notice">${icon('info')}<p><strong>Предпросмотр приложения.</strong> Расписание пока не обновляется автоматически. Актуальные анонсы — <a href="https://t.me/harekrishnabatumi" target="_blank" rel="noopener"><u>в канале храма ↗</u></a>.</p></div><section><div class="section-head"><h2>Программы храма</h2><a class="text-link" href="#schedule">Все программы ↗</a></div>${events.slice(0,3).map(eventRow).join('')}</section><section><div class="section-head"><h2>Рядом с вами</h2></div><div class="quick-grid"><a class="quick" href="#temple">${icon('pin')}<div><strong>Впервые в храме?</strong><span>Адрес, маршрут и ответы</span></div></a><a class="quick" href="#service">${icon('people')}<div><strong>Хочу быть полезным</strong><span>Найдите своё служение</span></div></a></div></section>`}
function schedule(){let list=events.filter(e=>filter==='Все'||e.type===filter);return intro('ВСТРЕЧИ, КОТОРЫЕ ОБЪЕДИНЯЮТ','Программы храма','Киртаны, лекции, праздники и встречи. Время указано по Батуми.')+`<div class="filter-bar" role="group" aria-label="Тип программы">${['Все','Программа','Киртан','Лекция','Харинама','Праздник'].map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><div class="notice">${icon('info')}<p>Регулярная программа — ориентир, пока организатор не подтвердил конкретную дату. Публикации за прошедшие дни сохранены с исходным статусом.</p></div>${list.length?list.map(eventRow).join(''):'<p class="sub">В этой категории пока нет опубликованных программ.</p>'}`}
